INSERT INTO `ceremony_effect_definitions` (`id`, `code`, `target_type`, `trigger_type`, `display_name`, `description`, `renderer_key`, `is_enabled`, `is_user_visible`, `manually_triggerable`, `display_order`, `config_json`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (1,'HIGHLIGHT','PROJECTOR','SIGNATURE_COMPLETED','서명란 강조','서명이 완료된 서명란을 강조합니다.','projector-signature-highlight',1,1,0,10,NULL,1,1,'2026-09-07 12:28:16','2026-09-07 12:28:16'),(2,'PULSE','PROJECTOR','SIGNATURE_COMPLETED','서명란 펄스','서명란을 부드럽게 확대하며 반복 강조합니다.','projector-signature-pulse',1,1,0,20,NULL,1,1,'2026-09-07 12:28:16','2026-09-07 12:28:16'),(3,'RIPPLE','PROJECTOR','SIGNATURE_COMPLETED','서명란 물결','서명란 바깥으로 퍼지는 물결 효과를 표시합니다.','projector-signature-ripple',1,1,0,30,NULL,1,1,'2026-09-07 12:28:16','2026-09-07 12:28:16'),(4,'FLASH','PROJECTOR','SIGNATURE_COMPLETED','서명란 플래시','서명이 완료된 서명란을 짧고 선명하게 강조합니다.','projector-signature-flash',1,1,0,40,NULL,1,1,'2026-09-07 12:28:16','2026-09-07 12:28:16'),(5,'CONFETTI','PROJECTOR','ALL_SIGNATURES_COMPLETED','축하 색종이','화면 위에서 아래로 자연스럽게 떨어지는 색종이 효과를 표시합니다.','projector-confetti',1,1,1,10,NULL,1,1,'2026-09-07 12:28:16','2026-09-08 01:02:11'),(6,'FIREWORKS','PROJECTOR','ALL_SIGNATURES_COMPLETED','축하 불꽃놀이','화면 전체에 불꽃놀이 효과를 표시합니다.','projector-fireworks',1,1,1,20,NULL,1,1,'2026-09-07 12:28:16','2026-09-08 01:02:11'),(7,'SPARKLE','PROJECTOR','ALL_SIGNATURES_COMPLETED','축하 별빛','화면 전체에 반짝이는 별빛 효과를 표시합니다.','projector-sparkle',1,1,1,30,NULL,1,1,'2026-09-07 12:28:16','2026-09-07 12:28:16'),(8,'AIR_SHOT','PROJECTOR','ALL_SIGNATURES_COMPLETED','에어샷 꽃가루','화면 하단에서 종이 꽃가루를 높이 쏘아 올린 뒤 자연스럽게 떨어뜨립니다.','projector-air-shot',1,1,1,40,NULL,1,1,'2026-09-07 12:28:16','2026-09-07 12:28:16'),(9,'PAPER_REEL','PROJECTOR','ALL_SIGNATURES_COMPLETED','페이퍼 릴','화면 좌우 하단에서 긴 종이 릴이 포물선으로 발사되어 떨어지는 연출을 표시합니다.','projector-paper-reel',1,1,1,50,NULL,1,1,'2026-09-07 12:28:16','2026-09-07 12:28:16');
